import{_ as n,a0 as l,w as d,s,ao as p,I as i,x as e,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在Linux下创建一个不可变更的文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下创建一个不可变更的文件 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下创建一个不可变更的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下创建一个不可变更的文件 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150123 How to make a file immutable on Linux","title":"如何在Linux下创建一个不可变更的文件","tag":"201505","desc":""},"relativePath":"201505/20150123 How to make a file immutable on Linux.md","filePath":"[post].md"}'),c={name:"201505/20150123 How to make a file immutable on Linux.md"};function u(m,t,x,f,h,L){const o=l("Link");return d(),s("div",null,[t[13]||(t[13]=p(`<h1 id="如何在linux下创建一个不可变更的文件" tabindex="-1">如何在Linux下创建一个不可变更的文件 <a class="header-anchor" href="#如何在linux下创建一个不可变更的文件" aria-label="Permalink to “如何在Linux下创建一个不可变更的文件”">​</a></h1><p>假如你想对Linux中的一些重要文件做写保护，这样它们就不能被删除或者被篡改成之前的版本或者其他东西，或者在其他情况下，你可能想避免某些配置文件被软件自动修改。使用<code>chown</code>和<code>chmod</code>命令修改文件的归属关系或者权限位是处理这种情况的一个解决方法，但这并不完美，因为这样无法避免有root权限的操作。这时<code>chattr</code>就派上用场了。</p><p><code>chattr</code>是一个可以设置或取消文件的标志位的Linux命令，它和标准的文件权限（读、写、执行）是分离的。与此相关的另一个命令是<code>lsattr</code>，它可以显示文件的哪些标志位被设置上了。最初只有EXT文件系统（EXT2/3/4）支持<code>chattr</code>和<code>lsattr</code>所管理的标志位，但现在很多其他的原生的Linux文件系统都支持了，比如XFS、Btrfs、ReiserFS等等。</p><p>在这个教程中，我会示范如果使用<code>chattr</code>来让Linux中的文件不可变更。</p><p><code>chattr</code>和<code>lsattr</code>命令是e2fsprogs包的一部分，它在所有现代Linux发行版都预装了。</p><p>下面是<code>chattr</code>的基本语法。</p><pre><code>$ chattr [-RVf] [操作符][标志位] 文件...
</code></pre><p>其中操作符可以是“+”（把选定的标志位添加到标志位列表）、“-”（从标志位列表中移除选定的标志位）、或者“=”（强制使用选定的标志位）。</p><p>下面是一些可用的标志位。</p><ul><li><strong>a</strong>: 只能以追加模式打开。</li><li><strong>A</strong>: 不能更新atime（文件访问时间）。</li><li><strong>c</strong>: 当被写入磁盘时被自动压缩。</li><li><strong>C</strong>: 关掉“写时复制”。</li><li><strong>i</strong>: 不可变更。</li><li><strong>s</strong>: 通过自动归零来安全删除。（LCTT 译注：一般情况文件被删后内容不会被修改，改标志位会使得文件被删后原有内容被“0”取代）</li></ul><h3 id="不可变更-标志位" tabindex="-1">“不可变更”标志位 <a class="header-anchor" href="#不可变更-标志位" aria-label="Permalink to ““不可变更”标志位”">​</a></h3><p>为了让一个文件不可变更，你需要按照如下方法为这个文件添加“不可变更”标志位。例如，对/etc/passwd文件做写保护：</p><pre><code>$ sudo chattr +i /etc/passwd
</code></pre><p>注意设置或取消一个文件的“不可变更”标志位是需要root用户权限的。现在检查该文件“不可变更”标志位是否被添加上了。</p><pre><code>$ lsattr /etc/passwd
</code></pre><p>一旦文件被设置为不可变更，任何用户都将无法修改该文件。即使是root用户也不可以修改、删除、覆盖、移动或者重命名这个文件。如果你想再次修改这个文件，需要先把“不可变更”标志位取消了。</p><p>用如下命令取消“不可变更”标志位：</p><pre><code>$ sudo chattr -i /etc/passwd
</code></pre><p><img src="https://farm9.staticflickr.com/8613/16152651317_076a65cf50_b.jpg" alt=""></p><p>如果你想让一个目录（比如/etc）连同它下边的所有内容不可变更，使用“-R”选项：</p><pre><code>$ sudo chattr -R +i /etc
</code></pre><h3 id="只可追加-标志位" tabindex="-1">“只可追加”标志位 <a class="header-anchor" href="#只可追加-标志位" aria-label="Permalink to ““只可追加”标志位”">​</a></h3><p>另一个有用的的标志位是“只可追加”，它只允许文件内容被追加的方式修改。你不能覆盖或者删除一个设置了“只可追加”标志位的文件。这个标志位在你想避免日志文件被意外清理掉的情况很有用。</p><p>和“不可变更”标志位类似，你可以使用如下命令让文件变成“只可追加”模式：</p><pre><code>$ sudo chattr +a /var/log/syslog
</code></pre><p>注意当你复制一个“不可变更”或者“只可追加”的文件到其他地方后，新文件不会保留这些标志位！</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>在这个教程中，我展示了如何使用<code>chattr</code>和<code>lsattr</code>命令来管理额外的文件标志位，来避免文件被篡改（意外或者其他情况）的方法。注意你不能将<code>chattr</code>作为一个安全措施，因为“不可变更”标志位可以很容易被取消掉。解决这个问题的一个可能的方式是限制<code>chattr</code>命令自身的可用性，或者去掉CAP_LINUX_IMMUTABLE内核权能标志。关于<code>chattr</code>以及可用的标志位的更多细节，请参考它的man手册。</p><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),a(o,{href:"http://xmodulo.com/make-file-immutable-linux.html"},{default:r(()=>[...t[0]||(t[0]=[e("http://xmodulo.com/make-file-immutable-linux.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),a(o,{href:"http://xmodulo.com/author/nanni"},{default:r(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),a(o,{href:"https://github.com/goreliu"},{default:r(()=>[...t[3]||(t[3]=[e("goreliu",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),a(o,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const b=n(c,[["render",u]]);export{C as __pageData,b as default};
